function lerpPose(a, b, t) {
  const out = {};
  for (const k of Object.keys(b)) {
    if (Array.isArray(b[k])) out[k] = [lerp(a[k][0], b[k][0], t), lerp(a[k][1], b[k][1], t)];
    else out[k] = lerp(a[k], b[k], t);
  }
  return out;
}

function withBreath(pose, t, intensity = 1) {
  const s = Math.sin(t * 1.7) * 1.6 * intensity;
  const s2 = Math.sin(t * 1.7 + 1.1) * 1.2 * intensity;
  return {
    ...pose,
    shoulder: [pose.shoulder[0], pose.shoulder[1] + s * 0.4],
    head: [pose.head[0] + s2 * 0.25, pose.head[1] + s * 0.5],
    faH: [pose.faH[0], pose.faH[1] + s * 0.7],
    baH: [pose.baH[0], pose.baH[1] + s2 * 0.6],
    faE: [pose.faE[0], pose.faE[1] + s * 0.4],
    baE: [pose.baE[0], pose.baE[1] + s2 * 0.4]
  };
}

export class ArenaRenderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.w = 0;
    this.h = 0;
    this.dpr = 1;
    this.groundY = 0;
    this.scale = 1;
    this.playerX = 0;
    this.enemyX = 0;
    this.raf = 0;
    this.last = 0;
    this.time = 0;
    this.effects = [];
    this.motes = [];
    this.shake = 0;
    this.flash = 0;
    this.running = false;
    this.fighters = null;
    this.ko = { player: false, enemy: false };
    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(canvas);
    this.resize();
    this.makeMotes();
  }

  makeMotes() {
    this.motes = Array.from({ length: 42 }, () => ({
      x: Math.random(), y: Math.random(),
      r: Math.random() * 1.4 + 0.35,
      speed: Math.random() * 0.012 + 0.004,
      drift: (Math.random() - 0.5) * 0.008,
      alpha: Math.random() * 0.34 + 0.08,
      phase: Math.random() * TAU
    }));
  }

  resize() {
    const rect = this.canvas.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.w = rect.width;
    this.h = rect.height;
    this.canvas.width = Math.round(rect.width * this.dpr);
    this.canvas.height = Math.round(rect.height * this.dpr);
    this.scale = clamp(this.h / 330, 0.72, 1.42);
    this.groundY = this.h * 0.845;
    this.playerX = this.w * (this.w < 620 ? 0.275 : 0.3);
    this.enemyX = this.w * (this.w < 620 ? 0.725 : 0.7);
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    if (!this.running) this.draw();
  }

  setFighters(player, enemy) {
    const now = performance.now();
    this.fighters = {
      player: { look: player.look, facing: 1, x: 0, state: 'idle', t0: now, dur: 1e9, flash: 0, glow: 0, hitCount: 0 },
      enemy: { look: enemy.look, facing: -1, x: 0, state: 'idle', t0: now, dur: 1e9, flash: 0, glow: 0, hitCount: 0 }
    };
    this.ko = { player: false, enemy: false };
    this.effects = [];
    this.shake = 0;
  }

  setEmblem(glyph) {
    this.emblem = glyph || '';
  }

  start() {
    if (this.running) return;
    this.running = true;
    this.last = performance.now();
    const loop = (t) => {
      if (!this.running) return;
      const dt = Math.min(0.05, (t - this.last) / 1000 || 0.016);
      this.last = t;
      this.time += dt;
      this.update(dt);
      this.draw();
      this.raf = requestAnimationFrame(loop);
    };
    this.raf = requestAnimationFrame(loop);
  }

  stop() {
    this.running = false;
    cancelAnimationFrame(this.raf);
    this.raf = 0;
  }

  destroy() {
    this.stop();
    this.resizeObserver.disconnect();
  }

  play(who, state, dur = 0.65) {
    const f = this.fighters?.[who];
    if (!f) return;
    f.state = state;
    f.t0 = performance.now();
    f.dur = dur * 1000;
    if (state === 'ko') this.ko[who] = true;
  }

  getPos(who) {
    const f = this.fighters?.[who];
    if (!f) return { x: this.w / 2, y: this.h / 2 };
    const x = who === 'player' ? this.playerX : this.enemyX;
    return {
      x,
      y: this.groundY - 148 * this.scale,
      headY: this.groundY - 178 * this.scale
    };
  }

  shakeScreen(amount = 6) {
    this.shake = Math.max(this.shake, amount);
  }

  flashScreen(amount = 0.18) {
    this.flash = Math.max(this.flash, amount);
  }

  spawnImpact(who, { heavy = false, color = '#d8b678', count = 14 } = {}) {
    const p = this.getPos(who);
    const dir = who === 'enemy' ? 1 : -1;
    const x = p.x + (who === 'enemy' ? -6 : 6) * this.scale;
    const y = p.y;
    this.effects.push({
      type: 'slash', x, y,
      angle: (Math.random() - 0.5) * 1.4 + (who === 'enemy' ? 0.2 : Math.PI - 0.2),
      rot: (Math.random() - 0.5) * 0.9,
      life: 0.24, max: 0.24,
      size: (heavy ? 56 : 38) * this.scale,
      color: heavy ? '#f0d49a' : '#e9dec6'
    });
    this.effects.push({
      type: 'ring', x, y, maxR: (heavy ? 60 : 38) * this.scale,
      life: 0.35, max: 0.35, color
    });
    const n = heavy ? count + 10 : count;
    for (let i = 0; i < n; i++) {
      const a = Math.random() * TAU;
      const sp = (Math.random() * (heavy ? 240 : 150) + 30) * this.scale;
      this.effects.push({
        type: 'spark',
        x: x + (Math.random() - 0.5) * 12,
        y: y + (Math.random() - 0.5) * 16,
        vx: Math.cos(a) * sp + dir * 40,
        vy: Math.sin(a) * sp - 30,
        r: (Math.random() * 2.6 + 0.8) * this.scale,
        life: Math.random() * 0.4 + 0.25, max: 0.65,
        color: Math.random() > 0.55 ? color : '#151510',
        gravity: 420
      });
    }
    this.shakeScreen(heavy ? 11 : 5.5);
    if (heavy) this.flashScreen(0.12);
  }

  spawnBlock(who) {
    const p = this.getPos(who);
    for (let i = 0; i < 2; i++) {
      this.effects.push({
        type: 'ring', x: p.x, y: p.y + 6, maxR: (36 + i * 20) * this.scale,
        life: 0.42 + i * 0.08, max: 0.5, color: '#7fb7b3'
      });
    }
    for (let i = 0; i < 8; i++) {
      const a = Math.random() * TAU;
      this.effects.push({
        type: 'spark', x: p.x, y: p.y + 6,
        vx: Math.cos(a) * 110 * this.scale, vy: Math.sin(a) * 80 * this.scale - 20,
        r: 1.6 * this.scale, life: 0.36, max: 0.36, color: '#9fd4cd', gravity: 100
      });
    }
    this.shakeScreen(2);
  }

  spawnDodge(who) {
    const p = this.getPos(who);
    for (let i = 0; i < 10; i++) {
      this.effects.push({
        type: 'streak', x: p.x + (Math.random() - 0.5) * 44 * this.scale,
        y: p.y + (Math.random() - 0.5) * 80 * this.scale,
        len: (18 + Math.random() * 30) * this.scale,
        life: 0.35, max: 0.35, color: '#9fd4cd'
      });
    }
  }

  spawnCast(who, color = '#9aae5a') {
    const p = this.getPos(who);
    for (let i = 0; i < 18; i++) {
      const a = Math.random() * TAU;
      const r = (18 + Math.random() * 30) * this.scale;
      this.effects.push({
        type: 'spark', x: p.x + Math.cos(a) * r, y: p.y + Math.sin(a) * r * 1.4 + 10,
        vx: Math.cos(a) * 12, vy: -45 - Math.random() * 55,
        r: (1.2 + Math.random() * 2) * this.scale,
        life: 0.55 + Math.random() * 0.35, max: 0.9, color, gravity: -30
      });
    }
    this.effects.push({ type: 'ring', x: p.x, y: p.y + 8, maxR: 60 * this.scale, life: 0.6, max: 0.6, color });
  }

  spawnBreak(who) {
    const p = this.getPos(who);
    for (let i = 0; i < 30; i++) {
      const a = Math.random() * TAU;
      const sp = 70 + Math.random() * 210;
      this.effects.push({
        type: 'spark', x: p.x, y: p.y + (Math.random() - 0.5) * 60,
        vx: Math.cos(a) * sp * this.scale, vy: Math.sin(a) * sp * this.scale - 60,
        r: (1 + Math.random() * 2.4) * this.scale,
        life: 0.4 + Math.random() * 0.5, max: 0.9, color: Math.random() > 0.4 ? '#f0d49a' : '#e05a44',
        gravity: 360
      });
    }
    this.effects.push({ type: 'ring', x: p.x, y: p.y, maxR: 100 * this.scale, life: 0.55, max: 0.55, color: '#f0d49a' });
    this.shakeScreen(14);
    this.flashScreen(0.2);
  }

  update(dt) {
    const now = performance.now();
    for (const f of Object.values(this.fighters || {})) {
      if (f.state !== 'ko' && f.state !== 'win' && f.state !== 'idle' && now - f.t0 > f.dur) {
        f.state = 'idle';
        f.t0 = now;
      }
      f.flash = Math.max(0, f.flash - dt * 5);
      f.glow = Math.max(0, f.glow - dt * 2.2);
    }
    this.shake *= Math.pow(0.0015, dt);
    if (this.shake < 0.1) this.shake = 0;
    this.flash *= Math.pow(0.02, dt);
    for (const e of this.effects) {
      e.life -= dt;
      if (e.type === 'spark') {
        e.x += e.vx * dt;
        e.y += e.vy * dt;
        e.vy += e.gravity * dt;
        e.vx *= Math.pow(0.3, dt);
      } else if (e.type === 'streak') {
        e.y -= dt * 12;
      }
    }
    this.effects = this.effects.filter(e => e.life > 0);
    for (const m of this.motes) {
      m.y -= m.speed * dt;
      m.x += m.drift * dt;
      if (m.y < -0.05) { m.y = 1.05; m.x = Math.random(); }
      if (m.x < -0.05) m.x = 1.05;
      if (m.x > 1.05) m.x = -0.05;
    }
  }

  poseFor(f, now) {
    const p = (now - f.t0) / f.dur;
    if (f.state === 'idle') return withBreath(POSES.idle, this.time + (f.facing > 0 ? 0 : 2.1));
    if (f.state === 'attack') {
      if (p < 0.24) return lerpPose(POSES.idle, POSES.wind, easeOut(p / 0.24));
      if (p < 0.42) return lerpPose(POSES.wind, POSES.attack, easeOut((p - 0.24) / 0.18));
      if (p < 0.62) return { ...POSES.attack };
      return lerpPose(POSES.attack, POSES.idle, easeOut(clamp((p - 0.62) / 0.38, 0, 1)));
    }
    if (f.state === 'hit') {
      if (p < 0.22) return POSES.hit;
      return lerpPose(POSES.hit, POSES.idle, easeOut(clamp((p - 0.22) / 0.78, 0, 1)));
    }
    if (f.state === 'guard') {
      if (p < 0.7) return lerpPose(POSES.idle, POSES.guard, easeOut(p / 0.16));
      return lerpPose(POSES.guard, POSES.idle, easeOut(clamp((p - 0.7) / 0.3, 0, 1)));
    }
    if (f.state === 'cast') {
      if (p < 0.2) return lerpPose(POSES.idle, POSES.cast, easeOut(p / 0.2));
      if (p < 0.7) return POSES.cast;
      return lerpPose(POSES.cast, POSES.idle, easeOut(clamp((p - 0.7) / 0.3, 0, 1)));
    }
    if (f.state === 'ko') return POSES.hit;
    if (f.state === 'win') return POSES.win;
    return POSES.idle;
  }

  draw() {
    const { ctx, w, h } = this;
    if (!w || !h) return;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    const sx = this.shake ? (Math.random() - 0.5) * this.shake : 0;
    const sy = this.shake ? (Math.random() - 0.5) * this.shake : 0;
    ctx.save();
    ctx.translate(sx, sy);
    this.drawBackground(ctx, w, h);
    if (this.fighters) {
      this.drawFighter(ctx, 'player');
      this.drawFighter(ctx, 'enemy');
    }
    this.drawEffects(ctx);
    ctx.restore();
    if (this.flash > 0.002) {
      ctx.fillStyle = `rgba(240,212,154,${this.flash})`;
      ctx.fillRect(0, 0, w, h);
    }
    this.drawVignette(ctx, w, h);
  }

  drawBackground(ctx, w, h) {
    const g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, '#080a08');
    g.addColorStop(0.46, '#17150f');
    g.addColorStop(0.78, '#2a1b15');
    g.addColorStop(1, '#0c0c08');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);

    // sun
    const sunX = w * 0.72;
    const sunY = h * 0.31;
    const sunR = clamp(Math.min(w, h) * 0.17, 52, 150);
    const halo = ctx.createRadialGradient(sunX, sunY, sunR * 0.2, sunX, sunY, sunR * 2.3);
    halo.addColorStop(0, 'rgba(197,72,54,.23)');
    halo.addColorStop(0.45, 'rgba(160,50,39,.08)');
    halo.addColorStop(1, 'rgba(160,50,39,0)');
    ctx.fillStyle = halo;
    ctx.fillRect(sunX - sunR * 2.4, sunY - sunR * 2.4, sunR * 4.8, sunR * 4.8);
    const sg = ctx.createRadialGradient(sunX - sunR * 0.25, sunY - sunR * 0.25, sunR * 0.1, sunX, sunY, sunR);
    sg.addColorStop(0, '#df7159');
    sg.addColorStop(0.55, '#b83f32');
    sg.addColorStop(1, '#6f241d');
    ctx.fillStyle = sg;
    ctx.beginPath();
    ctx.arc(sunX, sunY, sunR, 0, TAU);
    ctx.fill();
    // faint brush rings around the sun
    ctx.strokeStyle = 'rgba(240,212,154,.06)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.arc(sunX, sunY, sunR + 9 + i * 11, 0.2 + i, TAU - 0.4 + i);
      ctx.stroke();
    }

    // mist bands
    for (let i = 0; i < 3; i++) {
      const y = h * (0.36 + i * 0.09);
      const mg = ctx.createLinearGradient(0, y - 18, 0, y + 18);
      mg.addColorStop(0, 'rgba(233,222,198,0)');
      mg.addColorStop(0.5, `rgba(233,222,198,${0.028 - i * 0.005})`);
      mg.addColorStop(1, 'rgba(233,222,198,0)');
      ctx.fillStyle = mg;
      ctx.fillRect(0, y - 18, w, 36);
    }

    // mountains — three ink layers
    this.drawMountains(ctx, w, h, h * 0.68, 0.42, '#0f110c', 0.7);
    this.drawMountains(ctx, w, h, h * 0.76, 0.35, '#0a0c08', 0.9);

    // bamboo
    this.drawBamboo(ctx, w, h);

    // emblem behind enemy
    if (this.emblem) {
      ctx.save();
      ctx.font = `${Math.round(150 * this.scale)}px "Songti SC","Noto Serif CJK SC",serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = 'rgba(216,182,120,.035)';
      ctx.fillText(this.emblem, this.enemyX, this.groundY - 105 * this.scale);
      ctx.restore();
    }

    // ground
    const groundY = this.groundY;
    const gg = ctx.createLinearGradient(0, groundY - 20, 0, h);
    gg.addColorStop(0, '#141510');
    gg.addColorStop(0.28, '#0c0d09');
    gg.addColorStop(1, '#060705');
    ctx.fillStyle = gg;
    ctx.fillRect(0, groundY, w, h - groundY);

    // platform ellipse
    ctx.save();
    ctx.translate(w * 0.5, groundY + 8);
    ctx.scale(1, 0.17);
    const platform = ctx.createRadialGradient(0, 0, 20, 0, 0, w * 0.4);
    platform.addColorStop(0, 'rgba(216,182,120,.075)');
    platform.addColorStop(0.65, 'rgba(216,182,120,.02)');
    platform.addColorStop(1, 'rgba(216,182,120,0)');
    ctx.fillStyle = platform;
    ctx.beginPath();
    ctx.arc(0, 0, w * 0.42, 0, TAU);
    ctx.fill();
    ctx.restore();

    // perspective lines
    ctx.strokeStyle = 'rgba(216,182,120,.055)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 6; i++) {
      const y = groundY + 18 + i * i * 7;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.quadraticCurveTo(w * 0.5, y - 4, w, y);
      ctx.stroke();
    }
    // cracks
    ctx.strokeStyle = 'rgba(233,222,198,.045)';
    ctx.beginPath();
    ctx.moveTo(w * 0.12, groundY + 30);
    ctx.lineTo(w * 0.2, groundY + 42);
    ctx.lineTo(w * 0.18, groundY + 56);
    ctx.moveTo(w * 0.84, groundY + 24);
    ctx.lineTo(w * 0.78, groundY + 44);
    ctx.lineTo(w * 0.81, groundY + 58);
    ctx.stroke();

    // ambient motes
    for (const m of this.motes) {
      const a = m.alpha * (0.6 + 0.4 * Math.sin(this.time * 0.9 + m.phase));
      ctx.fillStyle = `rgba(240,212,154,${a})`;
      ctx.beginPath();
      ctx.arc(m.x * w, m.y * h, m.r, 0, TAU);
      ctx.fill();
    }
  }

  drawMountains(ctx, w, h, baseY, amp, color, alpha) {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(0, h);
    ctx.lineTo(0, baseY);
    const pts = [
      [0.05, 0.62], [0.12, 0.48], [0.18, 0.6], [0.27, 0.3],
      [0.34, 0.55], [0.4, 0.42], [0.48, 0.62], [0.56, 0.38],
      [0.63, 0.58], [0.7, 0.46], [0.78, 0.64], [0.87, 0.4],
      [0.94, 0.57], [1, 0.5]
    ];
    for (const [x, y] of pts) {
      ctx.lineTo(w * x, baseY - h * amp * (1 - y) * 1.15);
    }
    ctx.lineTo(w, h);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  drawBamboo(ctx, w, h) {
    const stalks = [
      { x: 0.035, lean: 0.012, h: 0.82, a: 0.5 },
      { x: 0.09, lean: -0.006, h: 0.66, a: 0.32 },
      { x: 0.14, lean: 0.02, h: 0.48, a: 0.18 },
      { x: 0.93, lean: -0.014, h: 0.76, a: 0.42 },
      { x: 0.975, lean: 0.008, h: 0.58, a: 0.26 }
    ];
    ctx.save();
    for (const s of stalks) {
      const topX = (s.x + s.lean) * w;
      const bottomX = s.x * w;
      const topY = h * (1 - s.h);
      ctx.strokeStyle = `rgba(6,5,4,${0.82 * s.a + 0.24})`;
      ctx.lineWidth = Math.max(2, w * 0.0045);
      ctx.beginPath();
      ctx.moveTo(bottomX, h);
      ctx.quadraticCurveTo((bottomX + topX) / 2, h * 0.55, topX, topY);
      ctx.stroke();
      // joints
      const segs = 6;
      ctx.lineWidth = 1;
      for (let i = 1; i < segs; i++) {
        const t = i / segs;
        const x = lerp(bottomX, topX, t);
        const y = lerp(h, topY, t);
        ctx.beginPath();
        ctx.moveTo(x - w * 0.005, y);
        ctx.lineTo(x + w * 0.006, y - 2);
        ctx.stroke();
      }
    }
    // leaves
    ctx.fillStyle = 'rgba(7,7,5,.72)';
    const leaves = [[0.11, 0.35, -0.5], [0.12, 0.4, 0.3], [0.09, 0.5, -0.9], [0.95, 0.36, 0.6], [0.96, 0.45, -0.4], [0.94, 0.55, 0.9]];
    for (const [x, y, rot] of leaves) {
      ctx.save();
      ctx.translate(w * x, h * y);
      ctx.rotate(rot);
      ctx.beginPath();
      ctx.ellipse(0, 0, w * 0.035, w * 0.008, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
  }

  drawFighter(ctx, who) {
    const f = this.fighters[who];
    if (!f) return;
    const now = performance.now();
    const pose = this.poseFor(f, now);
    const p = (now - f.t0) / f.dur;
    const baseX = who === 'player' ? this.playerX : this.enemyX;
    let x = baseX;
    let y = this.groundY;

    // lunge / recoil
    if (f.state === 'attack') {
      const lunge = Math.sin(clamp(p, 0, 1) * Math.PI) * 24 * this.scale;
      x += f.facing * lunge;
    }
    if (f.state === 'hit') {
      x += -f.facing * Math.sin(clamp(p, 0, 1) * Math.PI) * 8 * this.scale;
    }
    if (f.state === 'ko') {
      const t = clamp((now - f.t0) / 900, 0, 1);
      x += -f.facing * 30 * easeOut(t) * this.scale;
    }

    const bob = f.state === 'idle' ? Math.sin(this.time * 1.7 + (who === 'enemy' ? 1.5 : 0)) * 1.2 : 0;
    const scale = this.scale * (f.look.build || 1);

    // shadow
    ctx.save();
    ctx.translate(x, this.groundY + 2);
    ctx.scale(1, 0.2);
    const sh = ctx.createRadialGradient(0, 0, 2, 0, 0, 48 * scale);
    sh.addColorStop(0, 'rgba(0,0,0,.65)');
    sh.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = sh;
    ctx.beginPath();
    ctx.arc(0, 0, 48 * scale, 0, TAU);
    ctx.fill();
    ctx.restore();

    ctx.save();
    ctx.translate(x, y + bob);
    if (f.state === 'ko') {
      const t = clamp((now - f.t0) / 900, 0, 1);
      ctx.translate(-f.facing * 20 * scale, -6 * scale);
      ctx.rotate(-f.facing * 1.28 * easeOut(t));
      ctx.translate(0, 10 * scale);
    }
    ctx.scale(scale * f.facing, scale);
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';
    if (f.glow > 0) {
      ctx.shadowColor = 'rgba(240,212,154,.65)';
      ctx.shadowBlur = 18 * f.glow;
    }
    this.drawBody(ctx, f, pose);
    ctx.shadowBlur = 0;

    // hit flash overlay
    if (f.flash > 0.02) {
      ctx.globalCompositeOperation = 'source-atop';
      ctx.fillStyle = `rgba(255,190,150,${f.flash * 0.22})`;
      ctx.fillRect(-90, -190, 180, 200);
      ctx.globalCompositeOperation = 'source-over';
    }
    ctx.restore();
  }

  drawBody(ctx, f, pose) {
    const look = f.look;
    const skin = look.skin || '#c8a57c';
    const robe = look.robe || '#2f2b25';
    const robeDark = shade(robe, -14);
    const robeLight = shade(robe, 10);
    const trim = look.trim || '#c48263';
    const sash = look.sash || '#b23a2f';
    const hair = look.hair || '#14110e';
    const outline = 'rgba(4,4,3,.6)';

    const hip = pose.hip, sh = pose.shoulder, head = pose.head;
    const faE = pose.faE, faH = pose.faH, baE = pose.baE, baH = pose.baH;
    const flK = pose.flK, flF = pose.flF, blK = pose.blK, blF = pose.blF;

    // back leg
    this.limb(ctx, hip[0] - 6, hip[1] + 4, blK[0], blK[1], blF[0], blF[1], 17, robeDark, outline);
    this.foot(ctx, blF[0], blF[1], robeDark, f.facing);
    // robe skirt
    ctx.beginPath();
    ctx.moveTo(-18, -84);
    ctx.quadraticCurveTo(-26, -62, -23, -44);
    ctx.lineTo(24, -44);
    ctx.quadraticCurveTo(27, -64, 18, -84);
    ctx.closePath();
    ctx.fillStyle = robeDark;
    ctx.fill();
    ctx.strokeStyle = outline;
    ctx.lineWidth = 1.5;
    ctx.stroke();
    // robe skirt crease
    ctx.strokeStyle = 'rgba(0,0,0,.25)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-4, -78);
    ctx.lineTo(-9, -46);
    ctx.moveTo(7, -78);
    ctx.lineTo(12, -46);
    ctx.stroke();

    // back arm
    this.arm(ctx, sh[0] - 9, sh[1] + 4, baE[0], baE[1], baH[0], baH[1], robe, skin, outline, 11);

    // torso
    ctx.beginPath();
    ctx.moveTo(-17, -127);
    ctx.bezierCurveTo(-25, -118, -24, -98, -18, -82);
    ctx.lineTo(19, -82);
    ctx.bezierCurveTo(25, -99, 25, -118, 17, -127);
    ctx.closePath();
    const tg = ctx.createLinearGradient(-20, -130, 20, -80);
    tg.addColorStop(0, robeLight);
    tg.addColorStop(0.55, robe);
    tg.addColorStop(1, robeDark);
    ctx.fillStyle = tg;
    ctx.fill();
    ctx.strokeStyle = outline;
    ctx.lineWidth = 1.6;
    ctx.stroke();

    // collar
    ctx.strokeStyle = trim;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(-9, -126);
    ctx.lineTo(0, -110);
    ctx.lineTo(9, -126);
    ctx.stroke();

    // sash
    ctx.save();
    ctx.translate(0, -88);
    ctx.rotate(-0.05);
    ctx.fillStyle = sash;
    ctx.fillRect(-19, -4, 38, 9);
    ctx.fillStyle = 'rgba(0,0,0,.18)';
    ctx.fillRect(-19, 2, 38, 3);
    ctx.fillStyle = sash;
    ctx.beginPath();
    ctx.moveTo(15, 0);
    ctx.quadraticCurveTo(25, 8 + Math.sin(this.time * 2) * 3, 20, 22);
    ctx.lineTo(13, 18);
    ctx.quadraticCurveTo(18, 8, 12, 3);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // front leg
    this.limb(ctx, hip[0] + 5, hip[1] + 3, flK[0], flK[1], flF[0], flF[1], 18, robe, outline);
    this.foot(ctx, flF[0], flF[1], shade(robe, 4), f.facing);

    // neck
    ctx.strokeStyle = skin;
    ctx.lineWidth = 9;
    ctx.beginPath();
    ctx.moveTo(sh[0], sh[1] + 2);
    ctx.lineTo(head[0], head[1] + 13);
    ctx.stroke();

    // head
    ctx.save();
    ctx.translate(head[0], head[1]);
    ctx.rotate(pose.lean * 0.012);
    // hair back
    ctx.fillStyle = hair;
    ctx.beginPath();
    ctx.ellipse(-3, -2, 18, 19, 0, 0, TAU);
    ctx.fill();
    // face
    ctx.fillStyle = skin;
    ctx.beginPath();
    ctx.ellipse(2, 1, 15.2, 16.6, 0.05, 0, TAU);
    ctx.fill();
    // jaw shade
    ctx.fillStyle = 'rgba(0,0,0,.08)';
    ctx.beginPath();
    ctx.ellipse(4, 7, 10, 8, 0.1, 0, TAU);
    ctx.fill();
    // hair cap
    ctx.fillStyle = hair;
    ctx.beginPath();
    ctx.moveTo(-15, -3);
    ctx.quadraticCurveTo(-14, -21, 2, -19);
    ctx.quadraticCurveTo(18, -18, 17, -4);
    ctx.quadraticCurveTo(9, -12, -3, -11);
    ctx.quadraticCurveTo(-10, -10, -15, -3);
    ctx.fill();
    // topknot
    if (look.topknot) {
      ctx.fillStyle = hair;
      ctx.beginPath();
      ctx.arc(-4, -20, 6.5, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = trim;
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.arc(-4, -20, 6.5, 0, TAU);
      ctx.stroke();
    }
    if (look.shaved) {
      ctx.fillStyle = 'rgba(0,0,0,.06)';
      ctx.beginPath();
      ctx.ellipse(1, -7, 12, 9, 0, 0, TAU);
      ctx.fill();
    }
    // headband
    if (look.headband) {
      ctx.strokeStyle = look.headband;
      ctx.lineWidth = 3.4;
      ctx.beginPath();
      ctx.moveTo(-15, -7);
      ctx.lineTo(15, -8);
      ctx.stroke();
      ctx.strokeStyle = look.headband;
      ctx.lineWidth = 2.2;
      ctx.beginPath();
      ctx.moveTo(-14, -7);
      ctx.quadraticCurveTo(-24 - Math.sin(this.time * 2.4) * 3, -2, -29, 9);
      ctx.moveTo(-14, -5);
      ctx.quadraticCurveTo(-23, 2, -24, 13);
      ctx.stroke();
    }
    // eyes & brow
    ctx.strokeStyle = '#1b1510';
    ctx.lineWidth = 1.8;
    ctx.beginPath();
    ctx.moveTo(5, -1);
    ctx.lineTo(11, -2);
    ctx.stroke();
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    ctx.moveTo(5, -6);
    ctx.lineTo(12, -7);
    ctx.stroke();
    // nose/mouth
    ctx.strokeStyle = 'rgba(27,21,16,.6)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(13, 3);
    ctx.lineTo(11, 7);
    ctx.moveTo(6, 10);
    ctx.lineTo(12, 10);
    ctx.stroke();
    // scar
    if (look.scar) {
      ctx.strokeStyle = 'rgba(130,52,40,.8)';
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.moveTo(8, -13);
      ctx.lineTo(12, 3);
      ctx.stroke();
    }
    // mask
    if (look.masked) {
      ctx.fillStyle = shade(look.robe, -20);
      ctx.beginPath();
      ctx.moveTo(-12, 4);
      ctx.quadraticCurveTo(2, 20, 17, 4);
      ctx.lineTo(15, 12);
      ctx.quadraticCurveTo(2, 25, -12, 12);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();

    // front arm
    this.arm(ctx, sh[0] + 9, sh[1] + 5, faE[0], faE[1], faH[0], faH[1], robe, skin, outline, 12);

    // weapon
    this.drawWeapon(ctx, f, pose);

    // veil
    if (look.veil) {
      ctx.fillStyle = 'rgba(184,63,50,.12)';
      ctx.beginPath();
      ctx.moveTo(head[0] - 12, head[1] - 8);
      ctx.quadraticCurveTo(head[0] - 40, head[1] + 40, head[0] - 26, head[1] + 82);
      ctx.lineTo(head[0] - 6, head[1] + 70);
      ctx.quadraticCurveTo(head[0] - 22, head[1] + 30, head[0] + 2, head[1] - 6);
      ctx.closePath();
      ctx.fill();
    }
  }

  limb(ctx, x1, y1, x2, y2, x3, y3, width, color, outline) {
    ctx.strokeStyle = outline;
    ctx.lineWidth = width + 3;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.quadraticCurveTo(x2, y2, x3, y3);
    ctx.stroke();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.quadraticCurveTo(x2, y2, x3, y3);
    ctx.stroke();
  }

  arm(ctx, sx, sy, ex, ey, hx, hy, robe, skin, outline, width) {
    // sleeve to elbow
    ctx.strokeStyle = outline;
    ctx.lineWidth = width + 3;
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.quadraticCurveTo((sx + ex) / 2, (sy + ey) / 2 - 2, ex, ey);
    ctx.stroke();
    ctx.strokeStyle = robe;
    ctx.lineWidth = width;
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.quadraticCurveTo((sx + ex) / 2, (sy + ey) / 2 - 2, ex, ey);
    ctx.stroke();
    // forearm
    ctx.strokeStyle = outline;
    ctx.lineWidth = 9;
    ctx.beginPath();
    ctx.moveTo(ex, ey);
    ctx.lineTo(hx, hy);
    ctx.stroke();
    ctx.strokeStyle = skin;
    ctx.lineWidth = 6.5;
    ctx.beginPath();
    ctx.moveTo(ex, ey);
    ctx.lineTo(hx, hy);
    ctx.stroke();
    // hand
    ctx.fillStyle = skin;
    ctx.beginPath();
    ctx.arc(hx, hy, 4.6, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = outline;
    ctx.lineWidth = 1;
    ctx.stroke();
  }

  foot(ctx, x, y, color, facing) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.ellipse(x + 3 * facing, y - 1, 8, 3.6, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(4,4,3,.5)';
    ctx.lineWidth = 1;
    ctx.stroke();
  }

  drawWeapon(ctx, f, pose) {
    const look = f.look;
    const hx = pose.faH[0], hy = pose.faH[1];
    if (look.weapon === 'staff') {
      ctx.strokeStyle = 'rgba(4,4,3,.6)';
      ctx.lineWidth = 5.4;
      ctx.beginPath();
      ctx.moveTo(hx - 26, hy + 58);
      ctx.lineTo(hx + 22, hy - 64);
      ctx.stroke();
      ctx.strokeStyle = '#6b4c2f';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(hx - 26, hy + 58);
      ctx.lineTo(hx + 22, hy - 64);
      ctx.stroke();
      ctx.strokeStyle = 'rgba(216,182,120,.55)';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(hx - 26, hy + 58);
      ctx.lineTo(hx + 22, hy - 64);
      ctx.stroke();
    } else if (look.weapon === 'blades') {
      for (const [px, py, len, ang] of [[hx, hy, 26, -0.35], [pose.baH[0], pose.baH[1], 20, 0.15]]) {
        ctx.save();
        ctx.translate(px, py);
        ctx.rotate(ang);
        ctx.strokeStyle = 'rgba(4,4,3,.6)';
        ctx.lineWidth = 3.4;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(len, -2);
        ctx.stroke();
        ctx.strokeStyle = '#cfd6cc';
        ctx.lineWidth = 2.1;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(len, -2);
        ctx.stroke();
        ctx.restore();
      }
    } else if (look.weapon === 'fan') {
      ctx.save();
      ctx.translate(hx, hy);
      ctx.rotate(-0.5);
      ctx.fillStyle = 'rgba(216,182,120,.18)';
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.arc(0, 0, 20, -0.9, 0.5);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = 'rgba(216,182,120,.55)';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.arc(0, 0, 20, -0.9, 0.5);
      ctx.stroke();
      for (let i = 0; i < 4; i++) {
        const a = -0.75 + i * 0.33;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(Math.cos(a) * 20, Math.sin(a) * 20);
        ctx.stroke();
      }
      ctx.restore();
    }
  }

  drawEffects(ctx) {
    for (const e of this.effects) {
      const a = clamp(e.life / e.max, 0, 1);
      if (e.type === 'spark') {
        ctx.fillStyle = rgba(e.color.startsWith('#') ? e.color : '#f0d49a', a);
        ctx.beginPath();
        ctx.arc(e.x, e.y, e.r * (0.6 + a * 0.8), 0, TAU);
        ctx.fill();
      } else if (e.type === 'slash') {
        ctx.save();
        ctx.translate(e.x, e.y);
        ctx.rotate(e.angle + e.rot);
        ctx.strokeStyle = `rgba(244,228,196,${a * 0.95})`;
        ctx.lineWidth = 2.6 * a + 0.8;
        ctx.beginPath();
        ctx.arc(0, 0, e.size * (1.15 - a * 0.15), -0.85, 0.5);
        ctx.stroke();
        ctx.strokeStyle = `rgba(240,212,154,${a * 0.5})`;
        ctx.lineWidth = 6 * a;
        ctx.beginPath();
        ctx.arc(0, 0, e.size * 0.96, -0.9, 0.45);
        ctx.stroke();
        ctx.restore();
      } else if (e.type === 'ring') {
        const r = e.maxR * (1 - a * 0.72);
        ctx.strokeStyle = rgba(e.color.startsWith('#') ? e.color : '#f0d49a', a * 0.75);
        ctx.lineWidth = 2 + a * 2;
        ctx.beginPath();
        ctx.arc(e.x, e.y, r, 0, TAU);
        ctx.stroke();
      } else if (e.type === 'streak') {
        ctx.strokeStyle = `rgba(159,212,205,${a * 0.6})`;
        ctx.lineWidth = 1.4;
        ctx.beginPath();
        ctx.moveTo(e.x, e.y);
        ctx.lineTo(e.x, e.y + e.len);
        ctx.stroke();
      }
    }
  }

  drawVignette(ctx, w, h) {
    const v = ctx.createRadialGradient(w * 0.5, h * 0.48, Math.min(w, h) * 0.25, w * 0.5, h * 0.5, Math.max(w, h) * 0.72);
    v.addColorStop(0, 'rgba(5,6,4,0)');
    v.addColorStop(0.72, 'rgba(5,6,4,.16)');
    v.addColorStop(1, 'rgba(5,6,4,.62)');
    ctx.fillStyle = v;
    ctx.fillRect(0, 0, w, h);
  }
}

import { CARD_BY_ID, cardLevel, describeMove, getCardStats } from './data.js';

const wait = ms => new Promise(resolve => setTimeout(resolve, ms));
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function weightedPick(items, weightFn) {
  const weights = items.map(weightFn);
  const total = weights.reduce((a, b) => a + b, 0);
  if (total <= 0) return items[0] || null;
  let roll = Math.random() * total;
  for (let i = 0; i < items.length; i++) {
    roll -= weights[i];
    if (roll <= 0) return items[i];
  }
  return items[items.length - 1];
}

export class Battle {
  constructor({ state, enemyDef, enemyIndex, renderer, callbacks = {} }) {
    this.state = state;
    this.def = enemyDef;
    this.enemyIndex = enemyIndex;
    this.renderer = renderer;
    this.cb = callbacks;
    this.uid = 0;
    this.over = false;
    this.busy = true;
    this.turn = 1;
    this.logHistory = [];
    this.damageDealt = 0;
    this.maxHit = 0;
    this.postureBreaks = 0;
    this.cardsPlayed = 0;
    this.enemyLooks = enemyDef.look;

    const p = state.player;
    this.player = {
      hp: p.hp,
      maxHp: p.maxHp,
      block: 0,
      posture: 0,
      maxPosture: 100,
      chi: 0,
      maxChi: Math.min(6, 3 + (p.level >= 3 ? 1 : 0) + (p.level >= 6 ? 1 : 0)),
      level: p.level,
      stance: null,
      flow: 0,
      broken: 0,
      statuses: {}
    };

    this.enemy = {
      hp: enemyDef.hp,
      maxHp: enemyDef.hp,
      block: 0,
      posture: 0,
      maxPosture: enemyDef.posture,
      postureRegen: enemyDef.postureRegen,
      statuses: {},
      phase2: false,
      lastMove: null,
      intent: null,
      look: enemyDef.look
    };

    this.drawPile = shuffle(p.owned.map(id => {
      const level = cardLevel(id, p.upgrades);
      return {
        uid: ++this.uid,
        id,
        level,
        def: CARD_BY_ID[id],
        stats: getCardStats(id, p.upgrades)
      };
    }));
    this.hand = [];
    this.discardPile = [];
    this.exhaustPile = [];

    this.enemy.intent = this.pickIntent();
  }

  /* ---------- setup / snapshots ---------- */

  async start() {
    this.renderer?.setFighters(
      { look: this.playerLook() },
      { look: this.def.look }
    );
    this.renderer?.setEmblem(this.def.glyph);
    this.renderer?.start();
    this.log(`<b>${this.def.name}</b> steps onto the floor.`);
    this.banner(this.def.name.toUpperCase(), this.def.title, 'vermin');
    await wait(650);
    this.startPlayerTurn(true);
  }

  playerLook() {
    return {
      robe: '#24332b', trim: '#d8b678', sash: '#6fae8d', hair: '#1c1914',
      skin: '#c8a57c', build: 1.0, headband: '#e9dec6', topknot: true, weapon: 'none'
    };
  }

  emit() {
    try { this.cb.onUpdate?.(); } catch (err) { console.error(err); }
  }

  log(html) {
    this.logHistory.push(html);
    if (this.logHistory.length > 40) this.logHistory.shift();
    try { this.cb.onLog?.(html); } catch (err) { console.error(err); }
  }

  banner(title, sub = '', tone = '') {
    try { this.cb.onBanner?.(title, sub, tone); } catch (err) { console.error(err); }
  }

  float(who, text, cls = '') {
    try { this.cb.onFloat?.(who, text, cls); } catch (err) { console.error(err); }
  }

  toast(msg, bad = false) {
    try { this.cb.onToast?.(msg, bad); } catch (err) { console.error(err); }
  }

  /* ---------- deck ---------- */

  drawCards(n) {
    let drawn = 0;
    for (let i = 0; i < n; i++) {
      if (this.hand.length >= 10) break;
      if (!this.drawPile.length) {
        if (!this.discardPile.length) break;
        this.drawPile = shuffle(this.discardPile);
        this.discardPile = [];
        this.log('The discard pile is gathered and shuffled.');
      }
      const card = this.drawPile.pop();
      if (card) {
        this.hand.push(card);
        drawn++;
      }
    }
    if (drawn) this.cb.onDraw?.(drawn);
    return drawn;
  }

  discardHand() {
    if (this.hand.length) {
      this.discardPile.push(...this.hand);
      this.hand = [];
    }
  }

  cardDiscard(card) {
    if (card.stats.exhaust) this.exhaustPile.push(card);
    else this.discardPile.push(card);
  }

  /* ---------- turns ---------- */

  async startPlayerTurn(first = false) {
    if (this.over) return;
    this.busy = true;
    this.player.block = 0;
    this.player.posture = Math.max(0, this.player.posture - 20);
    this.player.broken = 0;

    if (this.player.statuses.stun > 0) {
      this.player.statuses.stun -= 1;
      if (this.player.statuses.stun <= 0) delete this.player.statuses.stun;
      this.player.chi = 0;
      this.emit();
      this.banner('STAGGERED', 'You lose this turn.', 'vermin');
      this.log('You are too dazed to act.');
      await wait(900);
      if (!this.over) this.runEnemyTurn();
      return;
    }

    if (!first) this.turn += 1;
    this.player.chi = this.player.maxChi;
    this.drawCards(5);
    this.busy = false;
    this.emit();
    try { this.cb.onTurnStart?.(); } catch { /* ignore */ }
    if (first) {
      this.log('Your move. Choose your techniques.');
    } else {
      this.log(`Round ${this.turn}. Your move.`);
    }
  }

  canPlay(card) {
    return !!card && !this.busy && !this.over && card.stats.cost <= this.player.chi;
  }

  async playCard(uid) {
    if (this.busy || this.over) return false;
    const idx = this.hand.findIndex(c => c.uid === uid);
    if (idx < 0) return false;
    const card = this.hand[idx];
    if (card.stats.cost > this.player.chi) {
      this.toast('Not enough Chi', true);
      return false;
    }
    this.busy = true;
    this.player.chi -= card.stats.cost;
    this.hand.splice(idx, 1);
    this.cardsPlayed += 1;
    this.cb.onCardPlayed?.(card);
    this.emit();
    this.cb.onSfx?.('card');

    // stance flow
    const same = this.player.stance === card.def.style;
    this.player.stance = card.def.style;
    this.player.flow = same ? Math.min(3, this.player.flow + 1) : 1;
    const flowBonus = (this.player.flow - 1) * 2;

    if (card.def.style && this.player.flow > 1) {
      this.log(`${card.def.style === 'tiger' ? '虎 Tiger' : card.def.style === 'crane' ? '鶴 Crane' : '蛇 Serpent'} flow <b>${this.player.flow}</b>.`);
    }

    await wait(150);
    await this.resolveCard(card, flowBonus);
    if (!this.over) {
      this.cardDiscard(card);
      this.busy = false;
      this.emit();
    }
    return true;
  }

  async resolveCard(card, flowBonus) {
    const s = card.stats;
    let focusUsed = false;
    if (s.dmg && this.player.statuses.focus > 0) {
      this.player.statuses.focus -= 1;
      if (this.player.statuses.focus <= 0) delete this.player.statuses.focus;
      focusUsed = true;
      this.float('player', 'FOCUS', 'info');
    }

    let firstBonus = flowBonus;
    if (s.postureBonus && this.enemy.posture >= 50) firstBonus += s.postureBonus;
    if (s.bleedBonus) firstBonus += (this.enemy.statuses.bleed || 0) * s.bleedBonus;

    if (s.dmg) {
      const hits = s.hits || 1;
      const heavy = s.dmg >= 12 || hits >= 3 || firstBonus >= 8;
      for (let h = 0; h < hits; h++) {
        if (this.over) return;
        this.renderer?.play('player', 'attack', 0.56);
        await wait(h === 0 ? 150 : 110);
        const bonus = h === 0 ? firstBonus : 0;
        const raw = s.dmg + (this.player.statuses.strength || 0) + bonus;
        this.hitEnemy(raw, {
          posture: s.posture || 0,
          focus: focusUsed,
          heavy
        });
        await wait(h === 0 ? 160 : 130);
        if (this.over) return;
      }
      if (s.dmg >= 12) this.renderer?.shakeScreen(7);
    } else if (s.block || s.recover) {
      this.renderer?.play('player', 'guard', 0.7);
      await wait(150);
    } else if (s.heal || s.chi || s.draw) {
      this.renderer?.play('player', 'cast', 0.75);
      this.renderer?.spawnCast('player', card.def.style === 'crane' ? '#7fb7b3' : card.def.style === 'serpent' ? '#9aae5a' : '#d8b678');
      await wait(140);
    }

    if (this.over) return;

    if (s.block) {
      this.player.block += s.block;
      this.float('player', `+${s.block} GUARD`, 'block');
      this.renderer?.spawnBlock?.('player');
      this.cb.onSfx?.('block');
      this.log(`You gain <b>${s.block}</b> Guard.`);
    }
    if (s.heal) {
      this.player.hp = Math.min(this.player.maxHp, this.player.hp + s.heal);
      this.float('player', `+${s.heal}`, 'heal');
      this.cb.onSfx?.('heal');
      this.log(`You recover <b>${s.heal}</b> health.`);
    }
    if (s.chi) {
      this.player.chi = Math.min(8, this.player.chi + s.chi);
      this.float('player', `+${s.chi} CHI`, 'info');
      this.cb.onSfx?.('chi');
      this.log(`You gather <b>${s.chi}</b> Chi.`);
    }
    if (s.draw) {
      const n = this.drawCards(s.draw);
      this.cb.onSfx?.('draw');
      this.log(`You draw <b>${n}</b> technique${n === 1 ? '' : 's'}.`);
    }
    if (s.recover) {
      this.player.posture = Math.max(0, this.player.posture - s.recover);
      this.float('player', `BALANCE +${s.recover}`, 'block');
      this.log(`You recover <b>${s.recover}</b> balance.`);
    }

    if (s.statuses?.self) {
      for (const [k, v] of Object.entries(s.statuses.self)) {
        this.applyStatus('player', k, v);
      }
    }
    if (s.statuses?.enemy && !this.over) {
      for (const [k, v] of Object.entries(s.statuses.enemy)) {
        this.applyStatus('enemy', k, v);
      }
    }

    if (focusUsed && s.dmg) this.cb.onSfx?.('buff');
    this.emit();
  }

  /* ---------- damage ---------- */

  hitEnemy(raw, { posture = 0, focus = false, heavy = false, isCounter = false } = {}) {
    if (this.over || this.enemy.hp <= 0) return;
    const enemy = this.enemy;

    if (!isCounter && enemy.statuses.dodge > 0) {
      enemy.statuses.dodge -= 1;
      if (enemy.statuses.dodge <= 0) delete enemy.statuses.dodge;
      this.float('enemy', 'DODGED', 'info');
      this.renderer?.spawnDodge('enemy');
      this.renderer?.play('enemy', 'cast', 0.4);
      this.cb.onSfx?.('dodge');
      this.log(`${this.def.name} slips aside. The blow finds only air.`);
      this.emit();
      return;
    }

    let dmg = raw;
    if (this.player.statuses.weak > 0) dmg *= 0.75;
    if (enemy.statuses.vulnerable > 0) dmg *= 1.3;
    if (focus) dmg *= 1.5;
    dmg = Math.max(1, Math.round(dmg));

    const absorbed = Math.min(enemy.block, dmg);
    enemy.block -= absorbed;
    const hpLoss = dmg - absorbed;
    enemy.hp = Math.max(0, enemy.hp - hpLoss);
    this.damageDealt += hpLoss;
    this.maxHit = Math.max(this.maxHit, hpLoss);

    if (hpLoss > 0) {
      this.float('enemy', `-${hpLoss}`, hpLoss >= 20 ? 'crit' : 'damage');
      this.renderer?.spawnImpact('enemy', { heavy, color: '#e05a44', count: heavy ? 20 : 12 });
      this.cb.onSfx?.(heavy ? 'heavy' : 'hit');
      this.renderer?.play('enemy', 'hit', 0.5);
    } else {
      this.float('enemy', 'BLOCKED', 'block');
      this.renderer?.spawnBlock('enemy');
      this.cb.onSfx?.('block');
    }

    if (posture > 0) {
      enemy.posture += posture;
      if (enemy.posture >= enemy.maxPosture && !this.over) {
        enemy.posture = 0;
        enemy.statuses.stun = (enemy.statuses.stun || 0) + 1;
        this.postureBreaks += 1;
        this.state.stats.bestPostureBreak = Math.max(this.state.stats.bestPostureBreak || 0, this.postureBreaks);
        this.banner('POSTURE BROKEN', `${this.def.name} loses their next action.`, 'jade');
        this.renderer?.spawnBreak('enemy');
        this.renderer?.play('enemy', 'hit', 0.8);
        this.cb.onSfx?.('break');
        this.log(`<b>${this.def.name}'s posture breaks!</b> They will lose their next action.`);
      }
    }

    if (enemy.statuses.counter > 0 && !isCounter) {
      const counter = enemy.statuses.counter;
      delete enemy.statuses.counter;
      this.float('enemy', 'COUNTER', 'info');
      this.cb.onSfx?.('block');
      this.log(`${this.def.name} turns the blow aside and counters for <b>${counter}</b>.`);
      this.hitPlayer(counter, { posture: 0, isCounter: true });
    }

    if (this.def.phase2At && !enemy.phase2 && enemy.hp > 0 && enemy.hp / enemy.maxHp <= this.def.phase2At) {
      this.enterPhase2();
    }

    this.emit();
    if (enemy.hp <= 0 && !this.over) this.finishWin();
  }

  hitPlayer(raw, { posture = 0, isCounter = false, heavy = false } = {}) {
    if (this.over || this.player.hp <= 0) return;
    const player = this.player;

    if (!isCounter && player.statuses.dodge > 0) {
      player.statuses.dodge -= 1;
      if (player.statuses.dodge <= 0) delete player.statuses.dodge;
      this.float('player', 'DODGED', 'info');
      this.renderer?.spawnDodge('player');
      this.renderer?.play('player', 'cast', 0.4);
      this.cb.onSfx?.('dodge');
      this.log('You slip aside. The blow finds only air.');
      this.emit();
      return;
    }

    let dmg = raw;
    if (this.enemy.statuses.weak > 0) dmg *= 0.75;
    if (player.statuses.vulnerable > 0) dmg *= 1.3;
    if (player.broken > 0) dmg *= 1.5;
    dmg = Math.max(1, Math.round(dmg));

    const absorbed = Math.min(player.block, dmg);
    player.block -= absorbed;
    const hpLoss = dmg - absorbed;
    player.hp = Math.max(0, player.hp - hpLoss);
    this.state.player.hp = player.hp;

    if (hpLoss > 0) {
      this.float('player', `-${hpLoss}`, hpLoss >= 18 ? 'crit' : 'damage');
      this.renderer?.spawnImpact('player', { heavy: hpLoss >= 15, color: '#e05a44', count: 14 });
      this.cb.onSfx?.(hpLoss >= 15 ? 'heavy' : 'hit');
      this.renderer?.play('player', 'hit', 0.5);
    } else {
      this.float('player', 'BLOCKED', 'block');
      this.renderer?.spawnBlock('player');
      this.cb.onSfx?.('block');
    }

    if (posture > 0) {
      player.posture += posture;
      if (player.posture >= player.maxPosture) {
        player.posture = 0;
        player.broken = 1;
        this.banner('BALANCE BROKEN', 'Incoming damage is increased by 50% this turn.', 'vermin');
        this.renderer?.spawnBreak('player');
        this.cb.onSfx?.('break');
        this.log('<b>Your balance breaks.</b> Guard yourself.');
      }
    }

    if (player.statuses.counter > 0 && !isCounter) {
      const counter = player.statuses.counter;
      delete player.statuses.counter;
      this.float('player', 'COUNTER', 'info');
      this.log(`You answer the blow for <b>${counter}</b>.`);
      this.hitEnemy(counter, { posture: 0, isCounter: true });
    }

    this.emit();
    if (player.hp <= 0 && !this.over) this.finishLose();
  }

  applyStatus(who, kind, amount) {
    const target = who === 'player' ? this.player : this.enemy;
    if (!target || amount <= 0) return;
    target.statuses[kind] = (target.statuses[kind] || 0) + amount;
    const label = kind.charAt(0).toUpperCase() + kind.slice(1);
    this.float(who, `${label.toUpperCase()} ${amount}`, kind === 'bleed' ? 'damage' : 'info');
    this.cb.onSfx?.(kind === 'bleed' ? 'debuff' : 'buff');
    this.renderer?.spawnCast(who, kind === 'bleed' ? '#b83f32' : kind === 'vulnerable' ? '#d76a45' : kind === 'weak' ? '#9aae5a' : '#d8b678');
    this.renderer?.play(who, 'cast', 0.55);
    this.emit();
  }

  enterPhase2() {
    const enemy = this.enemy;
    enemy.phase2 = true;
    enemy.statuses.strength = (enemy.statuses.strength || 0) + 2;
    enemy.block += 8;
    enemy.intent = this.pickIntent();
    this.banner('SECOND WIND', `${this.def.name} draws a deeper blade.`, 'vermin');
    this.log(`<b>${this.def.name} sheds their restraint.</b> Strength rises.`);
    this.renderer?.spawnCast('enemy', '#e05a44');
    this.renderer?.play('enemy', 'cast', 0.9);
    this.renderer?.shakeScreen(10);
    this.cb.onSfx?.('break');
    this.emit();
  }

  /* ---------- enemy turn ---------- */

  async runEnemyTurn() {
    if (this.over) return;
    this.busy = true;
    this.player.block = Math.max(0, this.player.block);
    this.enemy.block = 0;
    this.emit();
    await wait(420);
    if (this.over) return;

    if (this.enemy.statuses.stun > 0) {
      this.enemy.statuses.stun -= 1;
      if (this.enemy.statuses.stun <= 0) delete this.enemy.statuses.stun;
      this.banner('STAGGERED', `${this.def.name} loses their action.`, 'jade');
      this.log(`${this.def.name} is still reeling. Their action is lost.`);
      this.renderer?.play('enemy', 'hit', 0.7);
      await wait(800);
      this.enemy.posture = Math.min(this.enemy.maxPosture, this.enemy.posture + Math.round(this.enemy.postureRegen * 0.7));
      this.enemy.lastMove = this.enemy.intent?.id;
      this.enemy.intent = this.pickIntent();
      this.player.broken = 0;
      this.emit();
      await this.endEnemyTurn();
      return;
    }

    const move = this.enemy.intent || this.pickIntent();
    await this.executeMove(move);
    if (this.over) return;

    this.enemy.lastMove = move.id;
    if (this.enemy.hp > 0) {
      this.enemy.posture = Math.min(this.enemy.maxPosture, this.enemy.posture + this.enemy.postureRegen);
    }
    this.enemy.intent = this.pickIntent();
    this.player.broken = 0;
    await this.tickStatuses('enemy');
    if (this.over) return;
    this.emit();
    await this.endEnemyTurn();
  }

  async endEnemyTurn() {
    if (this.over) return;
    await wait(300);
    this.startPlayerTurn();
  }

  async executeMove(move) {
    if (!move) return;
    const enemy = this.enemy;
    this.enemy.block = 0;
    this.log(`<b>${this.def.name}</b> uses <b>${move.name}</b>.`);

    if (move.heal) {
      const before = enemy.hp;
      enemy.hp = Math.min(enemy.maxHp, enemy.hp + move.heal);
      const healed = enemy.hp - before;
      if (healed > 0) {
        this.float('enemy', `+${healed}`, 'heal');
        this.cb.onSfx?.('heal');
      }
      this.renderer?.spawnCast('enemy', '#7fb7b3');
    }
    if (move.block) {
      enemy.block += move.block;
      this.float('enemy', `+${move.block} GUARD`, 'block');
      this.renderer?.spawnBlock('enemy');
      this.cb.onSfx?.('block');
    }
    if (move.recover) {
      enemy.posture = Math.max(0, enemy.posture - move.recover);
      this.float('enemy', `BALANCE +${move.recover}`, 'block');
    }

    if (move.dmg) {
      const hits = move.hits || 1;
      for (let i = 0; i < hits; i++) {
        if (this.over) return;
        this.renderer?.play('enemy', 'attack', 0.56);
        await wait(i === 0 ? 180 : 110);
        const raw = move.dmg + (enemy.statuses.strength || 0);
        this.hitPlayer(raw, { posture: move.posture || 0, heavy: move.dmg + (enemy.statuses.strength || 0) >= 13 });
        await wait(i === 0 ? 150 : 110);
        if (this.over) return;
      }
    } else if (!move.heal && !move.block) {
      this.renderer?.play('enemy', 'cast', 0.7);
      this.renderer?.spawnCast('enemy', '#d8b678');
      await wait(220);
    }

    if (move.statuses?.self) {
      for (const [k, v] of Object.entries(move.statuses.self)) this.applyStatus('enemy', k, v);
    }
    if (move.statuses?.enemy && !this.over) {
      for (const [k, v] of Object.entries(move.statuses.enemy)) this.applyStatus('player', k, v);
    }

    if (move.statuses?.enemy) {
      this.log(describeMove(move) + '.');
    } else if (move.statuses?.self) {
      this.log(describeMove(move) + '.');
    }
    this.emit();
  }

  async tickStatuses(who) {
    const target = who === 'player' ? this.player : this.enemy;
    const st = target.statuses;
    if (st.bleed > 0) {
      const dmg = st.bleed;
      target.hp = Math.max(0, target.hp - dmg);
      this.float(who, `-${dmg} BLEED`, 'damage');
      this.cb.onSfx?.('debuff');
      this.renderer?.spawnImpact(who, { heavy: false, color: '#b83f32', count: 8 });
      this.log(`${who === 'player' ? 'You bleed' : `${this.def.name} bleeds`} for <b>${dmg}</b>.`);
      st.bleed -= 1;
      if (st.bleed <= 0) delete st.bleed;
      await wait(260);
      this.emit();
      if (target.hp <= 0) {
        if (who === 'player') this.finishLose();
        else this.finishWin();
        return;
      }
    }
    if (st.regen > 0) {
      const healed = Math.min(target.maxHp - target.hp, st.regen);
      if (healed > 0) {
        target.hp += healed;
        this.float(who, `+${healed}`, 'heal');
      }
    }
    for (const key of ['vulnerable', 'weak']) {
      if (st[key] > 0) {
        st[key] -= 1;
        if (st[key] <= 0) delete st[key];
      }
    }
    this.emit();
  }

  /* ---------- ending turn ---------- */

  async endTurn() {
    if (this.busy || this.over) return;
    this.busy = true;
    this.emit();
    this.log('You end your turn.');
    await this.tickStatuses('player');
    if (this.over) return;
    this.discardHand();
    this.emit();
    await wait(280);
    if (!this.over) await this.runEnemyTurn();
  }

  /* ---------- AI ---------- */

  pickIntent() {
    const enemy = this.enemy;
    const ratio = enemy.hp / enemy.maxHp;
    const all = this.def.moves || [];
    let candidates = all.filter(m => {
      if (m.phase2 && !enemy.phase2) return false;
      if (m.hpBelow && ratio > m.hpBelow) return false;
      if (m.heal && ratio > 0.95) return false;
      return true;
    });
    if (!candidates.length) candidates = all.filter(m => !m.phase2 || enemy.phase2);
    if (!candidates.length) candidates = all;
    const chosen = weightedPick(candidates, m => {
      let w = m.weight || 1;
      if (m.id === enemy.lastMove) w *= 0.35;
      return w;
    });
    return chosen || candidates[0];
  }

  intentDamage(move) {
    if (!move?.dmg) return 0;
    let dmg = move.dmg + (this.enemy.statuses.strength || 0);
    if (this.enemy.statuses.weak > 0) dmg *= 0.75;
    if (this.player.statuses.vulnerable > 0) dmg *= 1.3;
    if (this.player.broken > 0) dmg *= 1.5;
    return Math.max(1, Math.round(dmg));
  }

  /* ---------- finish ---------- */

  finishWin() {
    if (this.over) return;
    this.over = true;
    this.busy = true;
    this.enemy.hp = 0;
    this.state.player.hp = this.player.hp;
    this.state.stats.damageDealt = (this.state.stats.damageDealt || 0) + this.damageDealt;
    this.renderer?.play('enemy', 'ko', 1.2);
    this.renderer?.spawnBreak('enemy');
    this.renderer?.shakeScreen(12);
    this.cb.onSfx?.('win');
    this.log(`<b>${this.def.name} falls.</b> The floor is yours.`);
    this.emit();
    setTimeout(() => {
      this.renderer?.play('player', 'win', 1.2);
      this.cb.onWin?.(this.summary());
    }, 1050);
  }

  finishLose() {
    if (this.over) return;
    this.over = true;
    this.busy = true;
    this.player.hp = 0;
    this.state.player.hp = 0;
    this.state.stats.damageDealt = (this.state.stats.damageDealt || 0) + this.damageDealt;
    this.renderer?.play('player', 'ko', 1.2);
    this.renderer?.spawnBreak('player');
    this.cb.onSfx?.('lose');
    this.log('<b>You fall.</b> The path is not yet closed.');
    this.emit();
    setTimeout(() => this.cb.onLose?.(this.summary()), 1150);
  }

  summary() {
    return {
      turns: this.turn,
      hp: this.player.hp,
      maxHp: this.player.maxHp,
      damageDealt: this.damageDealt,
      maxHit: this.maxHit,
      postureBreaks: this.postureBreaks,
      cardsPlayed: this.cardsPlayed,
      enemy: this.def,
      enemyIndex: this.enemyIndex
    };
  }
}

