Design HTML:

```
function runStrikeMinigame({ card, part, bodyPart, enemy, parts }) {
  return new Promise(resolve => {
    $('#strike-game')?.remove();
    const target = bodyPart || BODY_PARTS[part];
    const center = 42 + Math.random() * 16; // 42-58
    const perfect = 7, good = 18, graze = 31;
    const left = center - graze, width = graze*2;
    // parts bars
    const partRows = Object.entries(BODY_PARTS).map(([key, meta]) => {
      const p = parts[key];
      const pct = Math.round(p.integrity / p.max * 100);
      return `<div class="strike-part-row ${p.crippled?'crippled':''} ${key===part?'target':''}">
        <span class="strike-part-name"><b>${meta.glyph}</b>${meta.label}</span>
        <span class="strike-part-bar"><i style="width:${pct}%"></i></span>
        <span class="strike-part-val">${p.crippled?'CRIPPLED':pct+'%'}</span>
      </div>`;
    }).join('');
    const el = document.createElement('div');
    el.id='strike-game';
    el.className='strike-overlay';
    el.innerHTML = `
      <div class="strike-panel" role="dialog" aria-modal="true" aria-label="Strike timing">
        <p class="strike-eyebrow">${esc(enemy.name)} · ${esc(card.def.name)}</p>
        <h2 class="strike-title">Strike the <span>${esc(target.label)}</span></h2>
        <p class="strike-hint">Stop the mark inside the bright band. Perfect blows injure the ${esc(target.label.toLowerCase())}.</p>
        <div class="strike-meter" id="strike-meter">
          <span class="strike-zone graze" style="left:${left}%;width:${width}%"></span>
          <span class="strike-zone good" style="left:${center-good}%;width:${good*2}%"></span>
          <span class="strike-zone perfect" style="left:${center-perfect}%;width:${perfect*2}%"></span>
          <span class="strike-marker" id="strike-marker"></span>
        </div>
        <div class="strike-readout"><span id="strike-readout">READY</span><span class="strike-key">SPACE / TAP</span></div>
        <button type="button" class="btn btn-primary strike-btn" id="strike-btn">Strike</button>
        <div class="strike-parts">${partRows}</div>
      </div>`;
    document.body.appendChild(el); // fixed overlay
    renderer?.setTargetPart?.(part);
    const marker = $('#strike-marker', el);
    const readout = $('#strike-readout', el);
    let done=false, raf=0, pos=center, last=performance.now(), dir=1, elapsed=0;
    const speed = 74; // percent per second
    const tick = (now) => {
      const dt = Math.min(0.05,(now-last)/1000);
      last=now;
      if (!done) {
        elapsed += dt;
        // triangle wave 4..96
        const span=92;
        pos = 4 + ((elapsed*speed) % (span*2));
        if (pos > 96) pos = 192 - pos;
        marker.style.left = pos + '%';
        raf = requestAnimationFrame(tick);
      }
    };
    raf = requestAnimationFrame(tick);
    const cleanup = () => {
      done=true;
      cancelAnimationFrame(raf);
      window.removeEventListener('keydown', onKey);
    };
    const strike = () => {
      if (done) return;
      cleanup();
      const dist=Math.abs(pos-center);
      let quality, mult, partDamage, title, sub, cls;
      if (dist <= perfect) { quality='perfect'; mult=1.6; partDamage=40; title='PERFECT'; sub=`${target.label} struck clean.`; cls='perfect'; }
      else if (dist <= good) { quality='good'; mult=1.05; partDamage=22; title='CLEAN HIT'; sub=`The ${target.label.toLowerCase()} buckles.`; cls='good'; }
      else if (dist <= graze) { quality='graze'; mult=0.55; partDamage=10; title='GRAZE'; sub='A glancing blow.'; cls='graze'; }
      else { quality='miss'; mult=0.15; partDamage=0; title='MISS'; sub='The strike finds only air.'; cls='miss'; }
      marker.classList.add('stopped', cls);
      readout.textContent = title;
      readout.className = cls;
      el.classList.add('resolved', cls);
      el.querySelector('.strike-hint').textContent = sub;
      const btn = el.querySelector('.strike-btn');
      if (btn) btn.disabled = true;
      if (quality === 'perfect') { sfx('heavy'); renderer?.shakeScreen(8); }
      else if (quality === 'good') sfx('hit');
      else if (quality === 'graze') sfx('block');
      else sfx('deny');
      setTimeout(() => {
        el.classList.add('out');
        setTimeout(() => { el.remove(); renderer?.setTargetPart?.(null); resolve({ quality, mult, partDamage }); }, 220);
      }, 720);
    };
    const onKey = (e) => {
      if (e.code === 'Space' || e.code === 'Enter') { e.preventDefault(); strike(); }
    };
    el.addEventListener('pointerdown', (e) => {
      if (e.target.closest('.strike-btn') || !e.target.closest('.strike-parts')) strike();
    });
    window.addEventListener('keydown', onKey);
    // Avoid click handler double firing; pointerdown handles it.
    setTimeout(() => el.classList.add('in'), 10);
  });
}
